def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r - 1][c] == 2 and grid[r + 1][c] == 2
                    and grid[r][c - 1] == 2 and grid[r][c + 1] == 2):
                centers.append((r, c))

    # Join neighboring diamond shapes when their centers share a row or column.
    for r in range(h):
        cols = sorted(c for rr, c in centers if rr == r)
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 2, b - 1):
                if out[r][c] == 0:
                    out[r][c] = 1

    for c in range(w):
        rows = sorted(r for r, cc in centers if cc == c)
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 2, b - 1):
                if out[r][c] == 0:
                    out[r][c] = 1

    return out
